import Accordion from "@marko-ui/shadcn/ui/accordion/accordion.marko";

static const items = [
  {
    value: "item-1",
    title: "Is it accessible?",
    content: "Yes. It adheres to the WAI-ARIA design pattern.",
  },
  {
    value: "item-2",
    title: "Is it styled?",
    content: "Yes. It comes with default styles that match the other components' aesthetic.",
  },
  {
    value: "item-3",
    title: "Is it animated?",
    content: "Yes. It's animated by default, but you can disable it if you prefer.",
  },
];

<Accordion items=items collapsible defaultValue=["item-1"] class="w-full max-w-md"/>

import Accordion from "@marko-ui/shadcn/ui/accordion/accordion.marko";

static const items = [
  {
    value: "item-1",
    title: "How do I reset my password?",
    content:
      "Click on 'Forgot Password' on the login page, enter your email address, and we'll send you a link to reset your password. The link will expire in 24 hours.",
  },
  {
    value: "item-2",
    title: "Can I change my subscription plan?",
    content:
      "Yes, you can upgrade or downgrade your plan at any time from your account settings. Changes will be reflected in your next billing cycle.",
  },
  {
    value: "item-3",
    title: "What payment methods do you accept?",
    content:
      "We accept all major credit cards, PayPal, and bank transfers. All payments are processed securely through our payment partners.",
  },
];

<Accordion items=items defaultValue=["item-1"] class="max-w-lg"/>

