<let/value=["item-1"]/>

<div class="w-full max-w-md">
  <p class="text-muted-foreground mb-4 text-sm">
    Open: ${value.join(", ") || "none"}
  </p>
  <Accordion
    items=items
    value=value
    valueChange(next) { value = next; }
  />
